{"script": "data = json.decode(repo.read("services.json"))
services = data["services"]
enabled = [s for s in services if s.get("enabled") == True]
names = sorted([s["name"] for s in enabled])
total = 0
for s in enabled:
    total = total + s["port"]
return {
    "total_services": len(services),
    "skipped_disabled": [s["name"] for s in services if not s.get("enabled") == True],
    "result": {"enabled": names, "port_sum": total},
    "changed_files": repo.status(),
}"}
